#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DType {
    /// Kind category: 'i' (signed integer), 'f' (float), 'b' (bool)
    pub kind: char,
    /// Size in bytes of one element
    pub itemsize: usize,
    /// Alignment in bytes (must be > 0 and <= itemsize per the problem)
    pub alignment: usize,
    /// Non-empty name (e.g., "int32")
    pub name: String,
    /// Signedness flag; only meaningful for integers here
    pub signed: bool,
}

fn dtype_for<T>(name: &str, kind: char, signed: bool) -> DType {
    let itemsize = core::mem::size_of::<T>();
    let mut alignment = core::mem::align_of::<T>();

    // Enforce the problem constraints explicitly.
    // On typical platforms align_of::<T>() <= size_of::<T>(), but we clamp just in case.
    if alignment > itemsize {
        alignment = itemsize;
    }

    debug_assert!(itemsize > 0);
    debug_assert!(alignment > 0);
    debug_assert!(alignment <= itemsize);
    debug_assert!(!name.is_empty());

    DType {
        kind,
        itemsize,
        alignment,
        name: name.to_string(),
        signed,
    }
}

/// Given a NumPy-like dtype string, return a descriptor with predefined attributes.
///
/// Assumes `type_spec` is one of:
/// "int8", "int16", "int32", "int64", "float32", "float64", "bool".
pub fn numpy_dtype(type_spec: &str) -> DType {
    match type_spec {
        "int8" => dtype_for::<i8>("int8", 'i', true),
        "int16" => dtype_for::<i16>("int16", 'i', true),
        "int32" => dtype_for::<i32>("int32", 'i', true),
        "int64" => dtype_for::<i64>("int64", 'i', true),
        "float32" => dtype_for::<f32>("float32", 'f', false),
        "float64" => dtype_for::<f64>("float64", 'f', false),
        "bool" => dtype_for::<bool>("bool", 'b', false),
        _ => panic!("unsupported dtype spec: {type_spec}"),
    }
}

